-- Exact public relation ACL parity with production, per role.
do $$ declare r record; begin
  for r in select n.nspname||'.'||c.relname obj from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','v','m','f','p') loop
    execute format('revoke all on table %s from public, anon, authenticated, service_role', r.obj);
  end loop;
end $$;
